import java.io.*;
import java.net.*;

public class EchoServer {
    public static void main(String[] args) throws Exception {
        try (ServerSocket server = new ServerSocket(19100, 50, InetAddress.getLoopbackAddress())) {
            System.out.println("listening on " + server.getLocalSocketAddress());
            Thread client = Thread.ofPlatform().start(() -> {
                try (Socket s = new Socket(InetAddress.getLoopbackAddress(), 19100)) {
                    System.out.println("client: local=" + s.getLocalPort()
                        + " remote=" + s.getPort());
                    PrintWriter out = new PrintWriter(s.getOutputStream(), true);
                    BufferedReader in = new BufferedReader(
                        new InputStreamReader(s.getInputStream()));
                    out.println("ping");
                    System.out.println("client: got '" + in.readLine() + "'");
                    out.println("quit");
                    System.out.println("client: got '" + in.readLine() + "'");
                } catch (IOException e) { e.printStackTrace(); }
            });
            try (Socket conn = server.accept()) {
                System.out.println("server: accepted " + conn.getRemoteSocketAddress()
                    + " on local port " + conn.getLocalPort());
                BufferedReader in = new BufferedReader(
                    new InputStreamReader(conn.getInputStream()));
                PrintWriter out = new PrintWriter(conn.getOutputStream(), true);
                String line;
                while ((line = in.readLine()) != null) {
                    if (line.equals("quit")) { out.println("bye"); break; }
                    out.println("echo:" + line);
                }
            }
            client.join();
        }
    }
}

import java.net.*;
import java.nio.charset.StandardCharsets;

public class UdpEcho {
    public static void main(String[] args) throws Exception {
        try (DatagramSocket server = new DatagramSocket(19091, InetAddress.getLoopbackAddress())) {
            Thread t = Thread.ofPlatform().start(() -> {
                try {
                    byte[] buf = new byte[512];
                    for (int i = 0; i < 2; i++) {
                        DatagramPacket p = new DatagramPacket(buf, buf.length);
                        server.receive(p);
                        System.out.println("server: " + p.getLength() + " bytes from "
                            + p.getAddress().getHostAddress() + ":" + p.getPort());
                        server.send(new DatagramPacket(p.getData(), p.getLength(),
                            p.getSocketAddress()));
                    }
                } catch (Exception e) { e.printStackTrace(); }
            });
            try (DatagramSocket client = new DatagramSocket()) {
                client.setSoTimeout(1000);
                System.out.println("client local port: " + (client.getLocalPort() > 0));
                for (String msg : new String[] {"hello", "datagram two"}) {
                    byte[] data = msg.getBytes(StandardCharsets.UTF_8);
                    client.send(new DatagramPacket(data, data.length,
                        InetAddress.getLoopbackAddress(), 19091));
                    DatagramPacket r = new DatagramPacket(new byte[512], 512);
                    client.receive(r);
                    System.out.println("client: echo '" + new String(r.getData(), 0, r.getLength(),
                        StandardCharsets.UTF_8) + "' from port " + r.getPort());
                }
            }
            t.join();
        }
        try (DatagramSocket c = new DatagramSocket()) {
            c.setSoTimeout(300);
            c.send(new DatagramPacket(new byte[1], 1, InetAddress.getLoopbackAddress(), 19099));
            c.receive(new DatagramPacket(new byte[8], 8));
        } catch (Exception e) {
            System.out.println("no listener: " + e.getClass().getSimpleName()
                + ": " + e.getMessage());
        }
    }
}

import java.io.*;
import java.net.*;
import jdk.net.ExtendedSocketOptions;

public class Opts {
    public static void main(String[] args) throws Exception {
        try (ServerSocket ss = new ServerSocket(0, 50, InetAddress.getLoopbackAddress());
             Socket c = new Socket(InetAddress.getLoopbackAddress(), ss.getLocalPort());
             Socket a = ss.accept()) {
            System.out.println("TCP_NODELAY      = " + c.getTcpNoDelay());
            System.out.println("SO_KEEPALIVE     = " + c.getKeepAlive());
            System.out.println("SO_TIMEOUT       = " + c.getSoTimeout() + " (0 = infinite)");
            System.out.println("SO_LINGER        = " + c.getSoLinger() + " (-1 = disabled)");
            System.out.println("SO_RCVBUF        = " + c.getReceiveBufferSize());
            System.out.println("SO_SNDBUF        = " + c.getSendBufferSize());
            System.out.println("server SO_REUSEADDR = " + ss.getReuseAddress());
            System.out.println("server SO_RCVBUF    = " + ss.getReceiveBufferSize());
            c.setKeepAlive(true);
            c.setOption(ExtendedSocketOptions.TCP_KEEPIDLE, 60);
            c.setOption(ExtendedSocketOptions.TCP_KEEPINTERVAL, 10);
            c.setOption(ExtendedSocketOptions.TCP_KEEPCOUNT, 3);
            System.out.println("keepalive idle/interval/count = "
                + c.getOption(ExtendedSocketOptions.TCP_KEEPIDLE) + "/"
                + c.getOption(ExtendedSocketOptions.TCP_KEEPINTERVAL) + "/"
                + c.getOption(ExtendedSocketOptions.TCP_KEEPCOUNT));
        }
        // RST via SO_LINGER 0
        try (ServerSocket ss = new ServerSocket(0, 5, InetAddress.getLoopbackAddress())) {
            Thread t = Thread.ofPlatform().start(() -> {
                try (Socket s = ss.accept()) {
                    s.setSoLinger(true, 0);   // close() sends RST instead of FIN
                } catch (IOException e) { e.printStackTrace(); }
            });
            try (Socket c = new Socket(InetAddress.getLoopbackAddress(), ss.getLocalPort())) {
                t.join();
                Thread.sleep(100);
                try { c.getInputStream().read(); }
                catch (IOException e) { System.out.println("after peer RST: " + e.getMessage()); }
            }
        }
        // FIN gives end of stream (-1), not an exception
        try (ServerSocket ss = new ServerSocket(0, 5, InetAddress.getLoopbackAddress())) {
            Thread t = Thread.ofPlatform().start(() -> {
                try (Socket s = ss.accept()) { } catch (IOException e) { e.printStackTrace(); }
            });
            try (Socket c = new Socket(InetAddress.getLoopbackAddress(), ss.getLocalPort())) {
                t.join();
                System.out.println("after peer FIN, read() = " + c.getInputStream().read());
            }
        }
        // UDP too large
        try (DatagramSocket d = new DatagramSocket()) {
            d.send(new DatagramPacket(new byte[70000], 70000, InetAddress.getLoopbackAddress(), 9));
        } catch (IOException e) {
            System.out.println("UDP 70000 bytes: " + e.getClass().getSimpleName()
                + ": " + e.getMessage());
        }
        try (DatagramSocket d = new DatagramSocket()) {
            d.send(new DatagramPacket(new byte[65507], 65507, InetAddress.getLoopbackAddress(), 9));
            System.out.println("UDP 65507 bytes: sent");
        }
    }
}

import java.io.*;
import java.net.*;
import java.util.concurrent.atomic.AtomicLong;

public class ZeroWindow {
    public static void main(String[] args) throws Exception {
        try (ServerSocket ss = new ServerSocket(0, 5, InetAddress.getLoopbackAddress())) {
            ss.setReceiveBufferSize(64 * 1024);
            AtomicLong sent = new AtomicLong();
            Socket client = new Socket(InetAddress.getLoopbackAddress(), ss.getLocalPort());
            client.setSendBufferSize(64 * 1024);
            Socket server = ss.accept();       // the server never calls read() for now
            Thread writer = Thread.ofPlatform().start(() -> {
                byte[] chunk = new byte[4096];
                try {
                    OutputStream out = client.getOutputStream();
                    for (int i = 0; i < 1024; i++) {       // 4 MiB in total
                        out.write(chunk);
                        sent.addAndGet(chunk.length);
                    }
                } catch (IOException e) { System.out.println("writer: " + e.getMessage()); }
            });
            Thread.sleep(500);
            long stalled = sent.get();
            Thread.sleep(500);
            System.out.println("bytes accepted by write() while the reader is idle: " + stalled);
            System.out.println("progress during the next 500 ms: "
                + (sent.get() - stalled) + " bytes");
            System.out.println("writer state: " + writer.getState());
            long total = 0;
            byte[] buf = new byte[65536];
            InputStream in = server.getInputStream();
            while (total < 4096L * 1024) {
                total += in.read(buf);
            }
            writer.join();
            System.out.println("after the reader started: received " + total
                + " bytes, writer state " + writer.getState());
            client.close();
            server.close();
        }
    }
}

import java.io.*;
import java.net.*;

public class Nagle {
    static long run(boolean noDelay) throws Exception {
        try (ServerSocket ss = new ServerSocket(0, 5, InetAddress.getLoopbackAddress())) {
            Thread srv = Thread.ofPlatform().daemon().start(() -> {
                try (Socket c = ss.accept()) {
                    InputStream in = c.getInputStream();
                    OutputStream out = c.getOutputStream();
                    byte[] b = new byte[16];
                    while (true) {
                        // a request is 2 writes: 4-byte header + 4-byte body
                        int got = 0;
                        while (got < 8) {
                            int n = in.read(b, got, 8 - got);
                            if (n < 0) return;
                            got += n;
                        }
                        out.write(1); out.flush();
                    }
                } catch (IOException e) { }
            });
            try (Socket s = new Socket(InetAddress.getLoopbackAddress(), ss.getLocalPort())) {
                s.setTcpNoDelay(noDelay);
                OutputStream out = s.getOutputStream();
                InputStream in = s.getInputStream();
                long t0 = System.nanoTime();
                for (int i = 0; i < 20; i++) {
                    out.write(new byte[4]); out.flush();   // write 1
                    out.write(new byte[4]); out.flush();   // write 2 (small, previous unACKed)
                    in.read();
                }
                return (System.nanoTime() - t0) / 20 / 1000;
            }
        }
    }
    public static void main(String[] a) throws Exception {
        run(true);
        System.out.println("TCP_NODELAY=true : " + run(true) + " us per request");
        System.out.println("TCP_NODELAY=false: " + run(false) + " us per request");
    }
}

public class CwndSim {
    public static void main(String[] args) {
        int cwnd = 1;          // in MSS; the initial window of 1 MSS keeps the example small
        int ssthresh = 16;
        System.out.println("RTT  cwnd  ssthresh  phase / event");
        for (int rtt = 0; rtt <= 23; rtt++) {
            String phase = cwnd < ssthresh ? "slow start" : "congestion avoidance";
            String event = "";
            System.out.printf("%3d  %4d  %8d  %s", rtt, cwnd, ssthresh, phase);
            if (rtt == 10) {                       // three duplicate ACKs
                ssthresh = Math.max(cwnd / 2, 2);
                cwnd = ssthresh;                   // fast recovery ends with cwnd = ssthresh
                event = "  <- 3 dup ACKs: ssthresh = cwnd/2, cwnd = ssthresh";
            } else if (rtt == 16) {                // retransmission timeout
                ssthresh = Math.max(cwnd / 2, 2);
                cwnd = 1;
                event = "  <- timeout: ssthresh = cwnd/2, cwnd = 1";
            } else if (cwnd < ssthresh) {
                cwnd = Math.min(cwnd * 2, ssthresh);   // doubling per RTT, capped at ssthresh
            } else {
                cwnd += 1;                             // one MSS per RTT
            }
            System.out.println(event);
        }
    }
}

import java.io.*;
import java.net.*;
import java.util.*;
import java.util.concurrent.*;

public class MultiEcho {
    static void handle(Socket s) {
        try (s) {
            BufferedReader in = new BufferedReader(
                            new InputStreamReader(s.getInputStream()));
            PrintWriter out = new PrintWriter(s.getOutputStream(), true);
            String line;
            while ((line = in.readLine()) != null) {
                out.println(Thread.currentThread().isVirtual() + ":" + line.toUpperCase());
            }
        } catch (IOException ignored) { }
    }

    public static void main(String[] args) throws Exception {
        ServerSocket server = new ServerSocket(19101, 128, InetAddress.getLoopbackAddress());
        Thread acceptor = Thread.ofPlatform().daemon().start(() -> {
            try {
                while (true) {
                    Socket s = server.accept();
                    Thread.ofVirtual().start(() -> handle(s));
                }
            } catch (IOException e) { /* closed */ }
        });
        int clients = 1000;
        try (ExecutorService pool = Executors.newVirtualThreadPerTaskExecutor()) {
            List<Future<String>> fs = new ArrayList<>();
            for (int i = 0; i < clients; i++) {
                final int id = i;
                fs.add(pool.submit(() -> {
                    try (Socket s = new Socket(InetAddress.getLoopbackAddress(), 19101)) {
                        PrintWriter out = new PrintWriter(s.getOutputStream(), true);
                        BufferedReader in = new BufferedReader(
                            new InputStreamReader(s.getInputStream()));
                        out.println("client" + id);
                        return in.readLine();
                    }
                }));
            }
            int ok = 0;
            String first = null;
            for (Future<String> f : fs) { String r = f.get(); if (first == null) first = r; ok++; }
            System.out.println(ok + " clients served concurrently; first reply = " + first);
        }
        server.close();
    }
}

import java.io.IOException;
import java.net.InetAddress;
import java.net.InetSocketAddress;
import java.net.Socket;
import java.nio.ByteBuffer;
import java.nio.channels.*;
import java.util.Iterator;

public class NioEcho {
    public static void main(String[] args) throws Exception {
        Selector selector = Selector.open();
        ServerSocketChannel server = ServerSocketChannel.open();
        server.bind(new InetSocketAddress(InetAddress.getLoopbackAddress(), 19108));
        server.configureBlocking(false);
        server.register(selector, SelectionKey.OP_ACCEPT);

        Thread loop = Thread.ofPlatform().name("selector-loop").start(() -> {
            ByteBuffer buf = ByteBuffer.allocate(1024);
            try {
                while (selector.isOpen()) {
                    selector.select();
                    Iterator<SelectionKey> it = selector.selectedKeys().iterator();
                    while (it.hasNext()) {
                        SelectionKey key = it.next();
                        it.remove();
                        if (key.isAcceptable()) {
                            SocketChannel ch = server.accept();
                            ch.configureBlocking(false);
                            ch.register(selector, SelectionKey.OP_READ);
                            System.out.println("accepted " + ch.getRemoteAddress());
                        } else if (key.isReadable()) {
                            SocketChannel ch = (SocketChannel) key.channel();
                            buf.clear();
                            int n = ch.read(buf);
                            if (n < 0) { ch.close(); System.out.println("peer closed"); continue; }
                            buf.flip();
                            ch.write(buf);   // may write fewer bytes; a real server must handle it
                        }
                    }
                }
            } catch (IOException | ClosedSelectorException e) { /* shutting down */ }
        });

        for (int i = 1; i <= 3; i++) {
            try (Socket s = new Socket(InetAddress.getLoopbackAddress(), 19108)) {
                s.getOutputStream().write(("msg" + i).getBytes());
                byte[] r = new byte[16];
                int n = s.getInputStream().read(r);
                System.out.println("client " + i + " got " + new String(r, 0, n)
                    + " (handled by thread " + loop.getName() + ")");
            }
        }
        Thread.sleep(200);
        selector.close();
        server.close();
        loop.join();
    }
}

import java.io.*;
import java.net.*;

public class Timeouts {
    public static void main(String[] args) throws Exception {
        // 1. Connection refused: nothing listens on the port
        try (Socket s = new Socket()) {
            s.connect(new InetSocketAddress("127.0.0.1", 19199), 1000);
        } catch (IOException e) {
            System.out.println("1) " + e.getClass().getSimpleName() + ": " + e.getMessage());
        }
        // 2. Read timeout: peer accepts but never sends
        try (ServerSocket silent = new ServerSocket(19102, 1, InetAddress.getLoopbackAddress());
             Socket c = new Socket(InetAddress.getLoopbackAddress(), 19102)) {
            c.setSoTimeout(500);
            long t0 = System.nanoTime();
            try {
                c.getInputStream().read();
            } catch (SocketTimeoutException e) {
                System.out.printf("2) %s: %s after %d ms; socket still open=%b%n",
                    e.getClass().getSimpleName(), e.getMessage(),
                    (System.nanoTime() - t0) / 1_000_000, !c.isClosed());
            }
        }
        // 3. Backlog: listen backlog 1, never accept, count successful connects
        try (ServerSocket full = new ServerSocket(19103, 1, InetAddress.getLoopbackAddress())) {
            int ok = 0;
            String last = "";
            java.util.List<Socket> keep = new java.util.ArrayList<>();
            for (int i = 0; i < 6; i++) {
                Socket s = new Socket();
                try {
                    s.connect(new InetSocketAddress("127.0.0.1", 19103), 500);
                    keep.add(s);
                    ok++;
                } catch (IOException e) {
                    last = e.getClass().getSimpleName() + ": " + e.getMessage();
                    break;
                }
            }
            System.out.println("3) completed with backlog=1, no accept(): " + ok
                + (last.isEmpty() ? "" : "; next -> " + last));
            for (Socket s : keep) s.close();
        }
    }
}

import java.io.*;
import java.net.*;

public class Reuse {
    static ServerSocket open(boolean reuse) throws IOException {
        ServerSocket ss = new ServerSocket();
        ss.setReuseAddress(reuse);
        ss.bind(new InetSocketAddress(InetAddress.getLoopbackAddress(), 19107));
        return ss;
    }
    public static void main(String[] args) throws Exception {
        System.out.println("default getReuseAddress() = " + new ServerSocket().getReuseAddress());
        ServerSocket ss = open(true);
        Socket c = new Socket(InetAddress.getLoopbackAddress(), 19107);
        Socket a = ss.accept();
        a.close();   // server side closes first -> TIME_WAIT stays on the server's port 19107
        c.getInputStream().read();
        c.close();
        ss.close();
        try (ServerSocket x = open(false)) {
            System.out.println("rebind with reuse=false: ok");
        } catch (BindException e) {
            System.out.println("rebind with reuse=false: " + e.getMessage());
        }
        try (ServerSocket x = open(true)) {
            System.out.println("rebind with reuse=true: ok");
        }
    }
}

import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;

public class Framing {
    static void writeFrame(DataOutputStream out, String msg) throws IOException {
        byte[] b = msg.getBytes(StandardCharsets.UTF_8);
        out.writeInt(b.length);
        out.write(b);
    }
    static String readFrame(DataInputStream in) throws IOException {
        int len = in.readInt();
        byte[] b = new byte[len];
        in.readFully(b);               // loops until all len bytes have arrived
        return new String(b, StandardCharsets.UTF_8);
    }
    public static void main(String[] args) throws Exception {
        try (ServerSocket server = new ServerSocket(19105, 5, InetAddress.getLoopbackAddress())) {
            Thread t = Thread.ofPlatform().start(() -> {
                try (Socket c = server.accept()) {
                    DataInputStream in = new DataInputStream(
                        new BufferedInputStream(c.getInputStream()));
                    for (int i = 0; i < 3; i++) {
                        System.out.println("server frame " + i + ": " + readFrame(in));
                    }
                } catch (IOException e) { e.printStackTrace(); }
            });
            try (Socket s = new Socket(InetAddress.getLoopbackAddress(), 19105)) {
                s.setTcpNoDelay(true);
                DataOutputStream out = new DataOutputStream(
                    new BufferedOutputStream(s.getOutputStream()));
                writeFrame(out, "alpha");
                writeFrame(out, "beta beta");
                writeFrame(out, "gamma");
                out.flush();   // three frames may share one segment; framing makes that harmless
            }
            t.join();
        }
        // The partial-read pitfall: read(byte[]) returns whatever is available
        try (ServerSocket server = new ServerSocket(19106, 5, InetAddress.getLoopbackAddress())) {
            Thread t = Thread.ofPlatform().start(() -> {
                try (Socket c = server.accept()) {
                    OutputStream o = c.getOutputStream();
                    o.write("12345".getBytes()); o.flush();
                    Thread.sleep(200);
                    o.write("67890".getBytes()); o.flush();
                } catch (Exception e) { e.printStackTrace(); }
            });
            try (Socket s = new Socket(InetAddress.getLoopbackAddress(), 19106)) {
                byte[] buf = new byte[10];
                int n = s.getInputStream().read(buf);
                System.out.println("single read(byte[10]) returned " + n + " bytes");
            }
            t.join();
        }
    }
}

import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;

public class Http3Client {
    public static void main(String[] args) throws Exception {
        HttpClient client = HttpClient.newBuilder()
            .version(HttpClient.Version.HTTP_3)      // preferred version
            .build();
        HttpRequest req = HttpRequest.newBuilder(URI.create("https://example.org/")).build();
        HttpResponse<String> resp = client.send(req, HttpResponse.BodyHandlers.ofString());
        System.out.println(resp.version() + " " + resp.statusCode());
    }
}
